    if not os.environ.get("NEATLOGS_API_KEY"):
        return False
    import neatlogs

    neatlogs.init(workflow_name=workflow, instrumentations=["langgraph", "langchain", "anthropic"], tags=tags or [])
    _state["enabled"] = True
