            out["turns"] += 1
            u = ev.get("usage") or {}
            cached = int(u.get("cached_input_tokens") or 0)
            usage["input_tokens"] += int(u.get("input_tokens") or 0) - cached
            usage["cache_read_input_tokens"] += cached
            usage["output_tokens"] += int(u.get("output_tokens") or 0)
